import os
import zipfile
import shutil
import subprocess
from robot.api import logger


class PrepareTechLogs(object):
    def __init__(
        self, logs_dir="/tmp/BtsSnapshot", tech_log_dir="TechLogs", zip_file="192.168.255.129_BTSLogFiles.zip"
    ):
        """
        :type logs_dir: dir where logs are collected
        """
        self.zip_file = zip_file
        self.logs_dir = logs_dir
        self.tech_dir = os.path.join(self.logs_dir, tech_log_dir)
        self.tech_log_dir = tech_log_dir

    def prepare_env(self):
        """
        Creates workspace directory
        """
        if os.path.exists(self.tech_dir):
            os.chdir(self.logs_dir)
            shutil.rmtree(self.tech_log_dir)
        try:
            os.mkdir(self.tech_dir)
        except Exception as e:
            raise Exception('Problem while executed makedirs on {}\n{}'.format(self.tech_dir, e))

    def unzip_tech_logs(self):
        """
        :type unzip_tech_logs: Extracting Technical logs to /tmp/TechLogs
        """
        try:
            zip_file_path = os.path.join(self.logs_dir, self.zip_file)
            zfile = zipfile.ZipFile(zip_file_path)
            zfile.extractall(self.tech_dir)
            zfile.close()
            logger.console(('New TechLogs extracted correctly from {} file'.format(zip_file_path)))
        except Exception as e:
            raise Exception('There is a problem with extracting TechLogs: {}\n{}'.format(zip_file_path, e))

    def unxz_tech_log(self, archives_list):
        """
        :type unxz_tech_logs: Extracting specific file from *xz file
        """
        for archive in archives_list:
            archive_path = os.path.join(self.tech_dir, archive)
            proc = subprocess.Popen(['unxz', archive_path], stdout=subprocess.PIPE)
            proc.communicate()
            if proc.returncode != 0:
                raise Exception('Problem while executed unxz on: {}'.format(archive_path))
            logger.console(('New TechLogs extracted correctly from {} file'.format(archive_path)))

    def decode_bin_to_txt(self, logs_list, decoder):
        """
        :type decode_bin_to_txt: Decode *.bin to *.txt file
        """
        decoder_path = '/tmp/plugins/' + decoder
        os.chmod(decoder_path, 755)
        for log in logs_list:
            cmd = [
                decoder_path,
                '--decode',
                os.path.join(self.tech_dir, log),
                '--output',
                '{}/{}.csv'.format(self.tech_dir, log),
            ]
            proc = subprocess.Popen(cmd, stdout=subprocess.PIPE)
            proc.communicate()
            if proc.returncode != 0:
                raise Exception('Problem while executed command: {}'.format(cmd))
            logger.console(("Decoded file: {}".format(log)))

    def post_clean(self):
        """
        Remove unnecessary files
        """
        files = os.listdir(self.tech_dir)
        files = [f for f in files if not f.endswith(".csv")]
        os.chdir(self.tech_dir)
        for f in files:
            os.remove(f)

    def prepare_tech_logs(self, tech_logs, decoder):
        """
        Method prepare text file from *.zip archive
        """
        self.unxz_tech_log(tech_logs)
        tech_logs = [log[:-3] for log in tech_logs]
        self.decode_bin_to_txt(tech_logs, decoder)


class MergeTestResults(object):
    def __init__(self, dest_file_path):
        logger.console('Feature analysis based on TechLogs')
        self.test_failed = False
        self.dest_file_path = dest_file_path
        self.dest_file_lines = []

    def merge_tech_log(self, tech_logs):
        """
        main function to analyzing tti_trace
        """
        self.tech_log_files = tech_logs
        self._open_tech_log_files()
        self._prepare_to_write()
        self._write_to_file()

    def _open_tech_log_files(self):
        for tech_log in self.tech_log_files:
            with open(tech_log, 'r') as f:
                self._add_core_column_to_file(f)

    def _add_core_column_to_file(self, log_obj):
        core = self._extract_core_number(log_obj)
        content = log_obj.readlines()
        if not self.dest_file_lines:
            self._add_first_row(content[1])

        content = self._extract_date(content[2:])
        content = [(date, '{},{}'.format(core, row)) for date, row in content]
        self.dest_file_lines.extend(content)

    def _extract_core_number(self, file_obj):
        file_name = file_obj.name.split('.')[0]
        return file_name.split("_")[1]

    def _extract_date(self, content):
        # content = [(datetime.strptime(l[:27], "%Y-%m-%yT%H:%M:%S.%fZ"), l) for l in content]
        content = [(line[:27], line) for line in content]
        return content

    def _add_first_row(self, first_row):
        """
        function that add first row
        """
        self.dest_file_lines.insert(0, '--, {}'.format(first_row))

    def _prepare_to_write(self):
        """
        function that prepare_to_sort
        """
        first_row = self.dest_file_lines.pop(0)
        self.dest_file_lines.sort()
        self.dest_file_lines = [line[1] for line in self.dest_file_lines]
        self.dest_file_lines.insert(0, first_row)

    def _write_to_file(self):
        """
        function that write to file
        """
        with open(self.dest_file_path, 'w') as f:
            f.write(''.join(self.dest_file_lines))
            logger.console(('Merged logs are sored in file: {}'.format(self.dest_file_path)))
